 C("rivet_migrations", "Rivet", "Jon", "schema-upgrade", [
  R("phases", "Additive migration phases", "Rivet adds the nullable column first, backfills existing rows second, and only then enables the non-null constraint. Readers must tolerate missing values during backfill."),
  R("code", "Backfill checkpoint writer", "saveBackfillCursor in migrations/cursor_store.sql persists the last completed primary key. MIGRATION_CURSOR advances only after the row batch commits.", kind="code-reference"),
  R("batch", "Backfill transaction bound", "Each Rivet backfill transaction covers at most two hundred rows. The next batch resumes after the last committed primary key, not after the last row read."),
  R("retry", "Backfill replay decision", "A retried batch may revisit rows, so the derived column assignment must be idempotent. The checkpoint is not advanced for an aborted transaction.", kind="decision"),
  R("old", "Former read-position checkpoint", "The pilot wrote its cursor after reading a batch, before committing the updated rows. A crash could skip the uncommitted batch.", status="superseded", revision="r1"),
  R("change", "Commit-bound cursor revision", "The cursor now advances in the same transaction as the batch's updated rows. This replaced the read-position checkpoint and closed the skipped-batch gap.", kind="decision", supersedes=["old"], level=2),
  R("export", "Data-export cursor", "The data-export task records the last emitted row number in an output file. It does not share schema-upgrade transaction checkpoints.", task="data-export"),
  R("observation", "Aborted batch rehearsal", "A synthetic failure before commit left both the derived values and migration cursor unchanged. Retrying then processed the same primary-key range.", kind="observation", epistemic="verified"),
  R("pref", "Jon's progress display preference", "Jon wants migration progress to count committed rows. Rows merely read into a pending batch should not increase the completed count.", kind="preference", level=2),
  R("guess", "Larger batch proposal", "Jon proposed increasing batches to two thousand rows, but no accepted change or lock-duration measurement supports the increase.", kind="hypothesis", epistemic="claimed"),
 ], [
  Q("identifier", "identifiers", "When does MIGRATION_CURSOR advance?", {"code":3,"batch":2,"change":2,"retry":2,"observation":2}, "The writer ties advancement to commit; batch, revision, retry and aborted-batch records explicitly corroborate commit-bound advancement."),
  Q("paraphrase", "paraphrases", "Can a failed Rivet backfill skip rows it had only read?", {"retry":3,"change":3,"observation":2,"code":2,"batch":2}, "Retry and atomic-cursor rules prevent the gap; writer, batch rule and aborted-batch rehearsal explicitly corroborate commit-bound recovery."),
  Q("history", "historical-revisions", "What made the r1 backfill cursor unsafe after a crash?", {"old":3}, "The historical read-before-commit behavior could skip uncommitted work.", statuses=["superseded"], revisions=["r1"]),
  Q("multi", "multi-record", "List the schema-upgrade phases and the committed batch size limit.", {"phases":3,"batch":3}, "Phase order and transaction bound are independent requested facts."),
  Q("pref", "preferences", "What should Jon count as completed migration progress?", {"pref":3,"code":1}, "The preference specifies committed rows; the checkpoint implementation provides supporting context."),
  Q("unapproved", "unsupported-hypotheses", "Which measured lock-duration result approves two-thousand-row backfill batches?", {}, "The larger batch is only proposed and has no measurement."),
  Q("observed", "observations", "What remained unchanged in Rivet's synthetic failure before batch commit?", {"observation":3}, "The rehearsal observed both derived values and cursor unchanged; general transaction policies are not evidence of an executed rehearsal.", epistemics=["verified"]),
 ]),
